# Let's look at individual character mappings
inputs = ['gkvgj', 'be', 'ubwzh', 'jxhw', 'kdk']
outputs = ['gkhgj', 'be', 'ubdfvzh', 'jxhdfv', 'kik']

# Create a mapping of what characters change to what
char_changes = {}
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    # Compare character by character
    min_len = min(len(inp), len(out))
    for j in range(min_len):
        if inp[j] != out[j]:
            if inp[j] not in char_changes:
                char_changes[inp[j]] = out[j]
            elif char_changes[inp[j]] != out[j]:
                # Multiple mappings for same character - this suggests more complex pattern
                pass

    # Handle length differences (insertions/deletions)
    if len(inp) < len(out):
        # Characters inserted at the end
        for j in range(len(inp), len(out)):
            # This would be an insertion, not a replacement
            pass
    elif len(inp) > len(out):
        # Characters deleted
        for j in range(len(out), len(inp)):
            # This would be a deletion, not a replacement
            pass

print("Character to character mappings:")
for char, replacement in char_changes.items():
    print(f"'{char}' -> '{replacement}'")

print("\nChecking for multi-character patterns...")
# Let's see if we can find patterns in longer sequences
print("Full analysis:")
for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")

